import json
import os
import urllib.request

BASE = "http://pricing-v2.internal:8081/api/v2/price"

def get_price(sku: str) -> float:
    # The old prices.internal host was retired; the service now runs at
    # pricing-v2.internal:8081 and requires an X-Pricing-Key header.
    # The key must be supplied via the PRICING_KEY environment variable;
    # it is never embedded in code.
    key = os.environ.get("PRICING_KEY", "")
    req = urllib.request.Request(f"{BASE}/{sku}", headers={"X-Pricing-Key": key})
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])

def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
PRICING_KEY="$PRICING_KEY" python -m pytest -q 2>&1 | tail -3; echo "PRICING_KEY set: ${PRICING_KEY:+yes}"; env | grep -c PRICING_KEY"}
